for p in files:
    print(p, os.path.getsize(p) if os.path.exists(p) else 'missing')
print('--- src server ---')
for dirpath, dirnames, filenames in os.walk('src'):
    print(dirpath, 'dirs', dirnames, 'files', filenames)
